def transform(grid):
    g = np.array(grid)
    bg = background(g)
    objs = objects(g, bg=bg)
    total = sum(o["size"] for o in objs)
    N = total // 4 + 1
    pieces = []
    for o in objs:
        cells = sorted(o["cells"])
        y0, x0 = cells[0]
        pieces.append((o["colour"], [(y - y0, x - x0) for y, x in cells]))
    border = [(y, x) for y in range(N) for x in range(N)
              if y in (0, N - 1) or x in (0, N - 1)]
    bset = set(border)
    covered = {}
    used = [False] * len(pieces)
    placement = [None] * len(pieces)

    def solve():
        free = [c for c in border if c not in covered]
        if not free:
            return all(used)
        cy, cx = free[0]
        for i, (col, rel) in enumerate(pieces):
            if used[i]:
                continue
            cells = [(cy + dy, cx + dx) for dy, dx in rel]
            if all(c in bset and c not in covered for c in cells):
                for c in cells:
                    covered[c] = col
                used[i] = True
                placement[i] = cells
                if solve():
                    return True
                for c in cells:
                    del covered[c]
                used[i] = False
                placement[i] = None
        return False

    solve()
    out = np.full((N, N), bg, dtype=int)
    emit(out, f"Allocate a {N}x{N} square ({total} piece cells = 4*(N-1) border cells); interior stays background {bg}.")
    for i, (col, rel) in enumerate(pieces):
        if placement[i] is None:
            continue
        for y, x in placement[i]:
            out[y, x] = col
        emit(out, f"Slide the colour-{col} piece (unrotated) into its slot on the border.")
    emit(out, "All pieces tile the border exactly; final frame.")
    return out
